//! Omission-aware typed context compilation for Worldgen P03 F01-F04.
use std::collections::BTreeSet;
use bioprism_foundation::{EvidenceState, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;

pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.research-context-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)] pub struct ContextFact { pub fact_id:String,pub statement:String,pub support_milli:u16,pub state:EvidenceState,pub evidence_digest:ContentHash,pub provenance_digest:ContentHash,pub artifact_digest:ContentHash,pub replay_identity:ContentHash,pub negative_result:bool,pub raw_data_local:bool,pub boundary:String }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)] pub struct ContextCompilationRequest { pub request_id:String,pub objective:String,pub scope:String,pub required_fact_order:Vec<String>,pub minimum_support_milli:u16,pub facts:Vec<ContextFact>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)] pub struct ContextCompilationReceipt { pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub objective:String,pub scope:String,pub disposition:String,pub required_fact_order:Vec<String>,pub resolved_fact_order:Vec<String>,pub missing_fact_order:Vec<String>,pub blocked_fact_order:Vec<String>,pub unknown_fact_order:Vec<String>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub context_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String }
#[derive(Debug,Error,Clone,PartialEq,Eq)] pub enum ContextCompilationError { #[error("invalid context request: {0}")] Invalid(String), #[error("context artifact failed: {0}")] Artifact(String), #[error("invalid context receipt: {0}")] Receipt(String) }
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])} fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}
impl ContextCompilationReceipt { pub fn validate(&self)->Result<(),ContextCompilationError>{ if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.objective.trim().is_empty()||self.scope.trim().is_empty()||self.required_fact_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.context_digest].into_iter().all(digest){return Err(ContextCompilationError::Receipt("context identity, boundary, locality, digests, or effects are incomplete".into()));} for v in [&self.required_fact_order,&self.resolved_fact_order,&self.missing_fact_order,&self.blocked_fact_order,&self.unknown_fact_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !ordered(v){return Err(ContextCompilationError::Receipt("context ordering is not canonical".into()));}} let req=self.required_fact_order.iter().cloned().collect::<BTreeSet<_>>();let states=self.resolved_fact_order.iter().chain(&self.missing_fact_order).chain(&self.blocked_fact_order).chain(&self.unknown_fact_order).cloned().collect::<Vec<_>>();if req.len()!=self.required_fact_order.len()||states.len()!=req.len()||states.iter().cloned().collect::<BTreeSet<_>>()!=req{return Err(ContextCompilationError::Receipt("context states do not partition required facts".into()));}if self.effect_receipts.iter().any(|e|!e.starts_with("compile:worldgen-research-context:")&&e!="block:unsafe-release"){return Err(ContextCompilationError::Receipt("context effect is outside compilation gate".into()));}Ok(())} }
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["research program lead","preclinical neuroscientist","downstream crate context consumer"],"behavior":format!("compile omission-aware typed research context for {scale}"),"value":"turns retrieval evidence into reusable context without inventing missing or protected facts","input_schema":input_schema,"output_schema":"CompiledResearchContext6@1","effects":["compile:worldgen-research-context","block:unsafe-release"],"permissions":["compile:local-research-context"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY})}
pub fn compile(request:&ContextCompilationRequest,feature_id:&str,version:&str,scale:&str,require_federation:bool)->Result<ContextCompilationReceipt,ContextCompilationError>{if request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||request.request_id.trim().is_empty()||request.objective.trim().is_empty()||request.scope.trim().is_empty()||request.required_fact_order.is_empty()||!ordered(&request.required_fact_order)||request.required_fact_order.iter().collect::<BTreeSet<_>>().len()!=request.required_fact_order.len()||!digest(&request.replay_identity){return Err(ContextCompilationError::Invalid("context identity, required facts, replay, locality, or boundary is invalid".into()));}let required=request.required_fact_order.iter().cloned().collect::<BTreeSet<_>>();let mut facts=request.facts.clone();facts.sort_by(|a,b|a.fact_id.cmp(&b.fact_id));let mut resolved=BTreeSet::new();let mut missing=BTreeSet::new();let mut blocked=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();for id in &required{match facts.iter().find(|f|f.fact_id==*id){None=>{missing.insert(id.clone());omissions.insert(format!("fact:{}:missing",id));},Some(f) if f.negative_result=>{blocked.insert(id.clone());negative.insert(format!("fact:{}:negative-result-retained",id));},Some(f) if !request.policy_allow||!request.protected_closure||!f.raw_data_local||f.boundary!=PRECLINICAL_BOUNDARY=>{blocked.insert(id.clone());omissions.insert(format!("fact:{}:policy-or-locality-blocked",id));},Some(f) if f.replay_identity!=request.replay_identity=>{unknown.insert(id.clone());uncertainty.insert(format!("fact:{}:replay-mismatch",id));},Some(f) if f.state==EvidenceState::Supported&&f.support_milli>=request.minimum_support_milli=>{resolved.insert(id.clone());},Some(f) if matches!(f.state,EvidenceState::Unknown|EvidenceState::Speculative)=>{unknown.insert(id.clone());uncertainty.insert(format!("fact:{}:state-unknown",id));},Some(f)=>{blocked.insert(id.clone());omissions.insert(format!("fact:{}:unsupported-or-below-threshold",f.fact_id));}}}if require_federation&&!request.federation_approved{omissions.insert("request:federation-approval-missing".into());}let authority=request.policy_allow&&request.protected_closure&&request.raw_data_local&&(!require_federation||request.federation_approved);let disposition=if !authority{"blocked"}else if resolved.is_empty(){"unknown"}else if resolved.len()==required.len()&&omissions.is_empty()&&uncertainty.is_empty()&&negative.is_empty(){"qualified"}else{"partial"};let effect_receipts=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("compile:worldgen-research-context:{}",request.request_id)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.request_id,"objective":request.objective,"scope":request.scope,"disposition":disposition,"required_fact_order":required,"resolved_fact_order":resolved,"missing_fact_order":missing,"blocked_fact_order":blocked,"unknown_fact_order":unknown,"omissions":omissions,"uncertainty":uncertainty,"negative_evidence":negative,"replay_identity":request.replay_identity,"boundary":PRECLINICAL_BOUNDARY});let context_digest=ContentHash::of_value(&payload).map_err(|e|ContextCompilationError::Artifact(e.to_string()))?;let artifact=json!({"artifact_id":format!("worldgen-research-context:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":context_digest,"boundary":PRECLINICAL_BOUNDARY});let receipt=ContextCompilationReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.request_id.clone(),objective:request.objective.clone(),scope:request.scope.clone(),disposition:disposition.into(),required_fact_order:request.required_fact_order.clone(),resolved_fact_order:resolved.into_iter().collect(),missing_fact_order:missing.into_iter().collect(),blocked_fact_order:blocked.into_iter().collect(),unknown_fact_order:unknown.into_iter().collect(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),negative_evidence:negative.into_iter().collect(),replay_identity:request.replay_identity.clone(),context_digest, effect_receipts,artifact,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->ContextCompilationRequest{let f=ContextFact{fact_id:"fact:a".into(),statement:"supported".into(),support_milli:900,state:EvidenceState::Supported,evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:h("r"),negative_result:false,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};ContextCompilationRequest{request_id:"ctx:req".into(),objective:"compile".into(),scope:"study:one".into(),required_fact_order:vec!["fact:a".into()],minimum_support_milli:500,facts:vec![f],replay_identity:h("r"),policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(compile(&req(),"AFA-worldgen-P03-F01","worldgen-local-research-context/1.0","local single-study",false).unwrap().disposition,"qualified")}#[test]fn missing_is_unknown(){let mut r=req();r.facts.clear();assert_eq!(compile(&r,"AFA-worldgen-P03-F01","worldgen-local-research-context/1.0","local single-study",false).unwrap().disposition,"unknown")}#[test]fn federation_blocks(){let mut r=req();r.federation_approved=false;assert_eq!(compile(&r,"AFA-worldgen-P03-F04","worldgen-federated-continual-research-context/1.0","federated continual/autonomous",true).unwrap().disposition,"blocked")}}
